'use strict';
// Scratch (MS10b): the long-chain corpus of core/tests/suites/tech-chain.test.js (LONG_CHAIN_PUZZLES: real minimal classic9
// puzzles dug by SG.testkit.dig from the seeded stream 161, fork 'minimal.<i>', whose stuck position after every technique
// below the chains and forcingChain with C = 6 has a shortest chain of 7 or 8 links), regenerated by index under the registered
// ladder (wxyzWing included), the way explore-real.js of MS07b made it. Prints, for every index of the range that qualifies
// (stuck, and the shortest chain of the whole scan, up to 12 links, has 7 or 8 links), the puzzle, and a check of the indices of the
// existing list. Usage (from generator/): node tests/artifacts/difficulty-v3/MS10b/long-chain-scan.js <from> <count> [verify]
const SG = require('./load.js');
const H = SG.techHelper;
const m9 = H.model('classic9');
const CS = SG.chainSearch;
const from = Number(process.argv[2] || 0);
const count = Number(process.argv[3] || 100);
const verify = process.argv[4] === 'verify';
const idsBefore = (id) => SG.techniques.list().filter((t) => t.variantScope === null && SG.techniques.get(id).order > t.order)
  .map((t) => t.id);
const below = idsBefore('forcingChainLong');
const rng = SG.testkit.rng.create(161);
const t0 = Date.now();
let qualifying = 0;
for (let i = from; i < from + count; i++) {
  const r = rng.fork('minimal.' + i);
  const solution = SG.testkit.randomSolution(m9, r.fork('grid'));
  const dug = SG.testkit.dig(m9, solution, r.fork('dig'), { symmetry: 'none', minClues: 0 });
  const puzzle = H.puzzleString(m9, dug.givens);
  if (verify) { console.log('#' + i + ' ' + puzzle); continue; }
  const before = CS.SHORT_MAX;
  CS.SHORT_MAX = 6;
  let state;
  try { state = H.stateAfter(m9, puzzle, below); } finally { CS.SHORT_MAX = before; }
  if (state.unsolvedCount === 0) continue;
  const ctx = SG.techniques.createContext(m9, {});
  const seam = CS.forcing(m9, state, ctx, { id: 'x', minLength: 1, maxLength: 12, workLimit: null });
  if (seam === null) continue;
  const len = seam.i18nArgs.length;
  if (len !== 7 && len !== 8) continue;
  qualifying++;
  console.log("'" + puzzle + "', // #" + i + ': ' + len + ' links');
}
console.error('scanned ' + count + ' from ' + from + ', qualifying ' + qualifying + ', ' + ((Date.now() - t0) / 1000).toFixed(1) + ' s');
